{
    UserBack myUser;
    if (!IsAuth(out myUser))
        return new List<Client>().AsQueryable();
    try
    {
        if (myUser.IsSystemManager==true || myUser.IsFilialManager == true )
        {
            return _db.Context.Clients.Where(e => e.MainUserId==myUser.MainUserId).OrderBy(q => q.Adress);
        }

        if (myUser.IsClientManager==true)
        {
            string Client = myUser.Client;
            string[] Clients = Client.Split(',');
            int[] ClientsI = new int[Clients.Length];
            for(var i=0;i<Clients.Length;i++)
            {
                ClientsI[i] = int.Parse(Clients[i]);
            }

            return _db.Context.Clients.Where(e => ClientsI.Contains(e.Id) && e.MainUserId==myUser.MainUserId).OrderBy(q => q.Adress);
        }
        else
        {

            return _db.Context.Clients.Where(e =>  e.MainUserId==myUser.MainUserId).OrderBy(q => q.Adress);
        }
    }
    catch(Exception em)
    {
        return new List<Client>().AsQueryable();
    }
}

